const header=document.querySelector('#header'),menu=document.querySelector('.menu'),nav=document.querySelector('#nav');
const updateHeader=()=>header.classList.toggle('scrolled',window.scrollY>40);updateHeader();window.addEventListener('scroll',updateHeader,{passive:true});
function closeMenu(){nav.classList.remove('open');menu.setAttribute('aria-expanded','false');menu.setAttribute('aria-label','Mở menu')}
menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';nav.classList.toggle('open',open);menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'Đóng menu':'Mở menu')});
nav.querySelectorAll('a').forEach(link=>link.addEventListener('click',closeMenu));document.addEventListener('keydown',event=>{if(event.key==='Escape')closeMenu()});
const apartments={'2pn':{title:'Căn hộ 2 phòng ngủ',tag:'GỌN GÀNG & KẾT NỐI',description:'Gợi ý cho gia đình trẻ muốn cân bằng không gian sinh hoạt chung với hai phòng ngủ riêng.',bedrooms:'2 phòng ngủ',focus:'Phòng khách, bếp & logia',label:'Căn hộ 2PN',image:'room-living-0.jpg'},'2pnplus':{title:'Căn hộ 2 phòng ngủ + 1',tag:'THÊM KHÔNG GIAN LINH HOẠT',description:'Một khoảng không gian bổ sung để bạn cân nhắc góc làm việc, đọc sách hoặc nhu cầu riêng của gia đình. Công năng cụ thể theo mặt bằng từng căn.',bedrooms:'2 phòng ngủ + không gian bổ sung',focus:'Vị trí và công năng khu vực +1',label:'Căn hộ 2PN + 1',image:'room-living-4.jpg'},'3pn':{title:'Căn hộ 3 phòng ngủ',tag:'RIÊNG TƯ & SUM VẦY',description:'Gợi ý cho gia đình nhiều thành viên, cần ba phòng ngủ và không gian sinh hoạt chung. Hãy đối chiếu diện tích và bố trí thực tế của từng phương án.',bedrooms:'3 phòng ngủ',focus:'Bố trí phòng & diện tích sinh hoạt',label:'Căn hộ 3PN',image:'room-living-1.jpg'}};
const tabs=[...document.querySelectorAll('[data-apartment]')];function selectApartment(tab){const p=apartments[tab.dataset.apartment];tabs.forEach(t=>{const active=t===tab;t.setAttribute('aria-selected',String(active));t.tabIndex=active?0:-1});document.querySelector('#apartment-panel').setAttribute('aria-labelledby',tab.id);for(const [id,value] of Object.entries({'apartment-tag':p.tag,'apartment-title':p.title,'apartment-description':p.description,'apartment-bedrooms':p.bedrooms,'apartment-focus':p.focus}))document.getElementById(id).textContent=value;document.querySelector('#apartment-image').src='assets/'+p.image;document.querySelector('#apartment-image').alt='Ảnh tư liệu căn hộ mẫu, không đại diện riêng cho loại hình '+p.label;document.querySelector('#apartment-cta').innerHTML='Tư vấn '+p.label.toLowerCase()+' <span>↗</span>';document.querySelector('[name=property]').value=p.label}
tabs.forEach((tab,index)=>{tab.addEventListener('click',()=>selectApartment(tab));tab.addEventListener('keydown',e=>{let next;if(e.key==='ArrowRight')next=(index+1)%tabs.length;else if(e.key==='ArrowLeft')next=(index+tabs.length-1)%tabs.length;else if(e.key==='Home')next=0;else if(e.key==='End')next=tabs.length-1;if(next!==undefined){e.preventDefault();selectApartment(tabs[next]);tabs[next].focus()}})});
const roomSets=[{key:'living',label:'Phòng khách',files:[0,1,2,3,4,5]},{key:'master',label:'Phòng ngủ lớn',files:[1,2,3]},{key:'kids',label:'Phòng trẻ em',files:[1,2]}];
const grid=document.querySelector('#room-grid');roomSets.forEach(group=>group.files.forEach((number,index)=>{const button=document.createElement('button');button.type='button';button.className='zoom-image room-photo';button.dataset.room=group.key;button.dataset.image='assets/room-'+group.key+'-'+number+'.jpg';button.dataset.caption=group.label+' — tư liệu AHS Property do người dùng cung cấp; không phải cam kết nội thất bàn giao';button.hidden=group.key!=='living';const img=document.createElement('img');img.src=button.dataset.image;img.alt=group.label+' — góc nhìn '+(index+1);img.loading='lazy';img.decoding='async';const caption=document.createElement('span');caption.textContent=group.label+' / '+String(index+1).padStart(2,'0')+' ↗';button.append(img,caption);grid.append(button)}));
document.querySelectorAll('[data-room-filter]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('[data-room-filter]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));grid.querySelectorAll('[data-room]').forEach(photo=>photo.hidden=photo.dataset.room!==button.dataset.roomFilter)}));
const imageDialog=document.querySelector('#image-dialog');document.querySelectorAll('.zoom-image').forEach(button=>button.addEventListener('click',()=>{imageDialog.querySelector('img').src=button.dataset.image;imageDialog.querySelector('img').alt=button.dataset.caption;imageDialog.querySelector('p').textContent=button.dataset.caption;imageDialog.showModal()}));
document.querySelectorAll('dialog').forEach(dialog=>{dialog.querySelector('.close').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}})});document.querySelector('#privacy-button').addEventListener('click',()=>document.querySelector('#privacy-dialog').showModal());
document.querySelector('#tour-start').addEventListener('click',()=>{const iframe=document.createElement('iframe');iframe.src='https://kuula.co/share/collection/7TkRJ?logo=0&info=1&fs=1&vr=0&sd=1&thumbs=1';iframe.title='Tham quan 360° căn hộ mẫu An Lạc Green Symphony — AHS Property trên Kuula';iframe.allowFullscreen=true;iframe.allow='fullscreen; xr-spatial-tracking';iframe.referrerPolicy='strict-origin-when-cross-origin';document.querySelector('#tour-viewer').replaceChildren(iframe)});
let inquiry='';document.querySelector('#inquiry-form').addEventListener('submit',e=>{e.preventDefault();const form=e.currentTarget;if(!form.reportValidity())return;const data=new FormData(form);inquiry='Kính gửi Master Vinh Quang,\n\nTôi muốn tìm hiểu chung cư Moonlight 2 tại Anlac Green Symphony.\nHọ tên: '+String(data.get('name')).trim()+'\nĐiện thoại: '+String(data.get('phone')).trim()+'\nLoại căn hộ: '+data.get('property')+'\nNhu cầu: '+(String(data.get('message')).trim()||'Mong được tư vấn thêm.')+'\n\nVui lòng phản hồi thông tin và bước tiếp theo phù hợp. Xin cảm ơn.';document.querySelector('#form-result').hidden=false;document.querySelector('#copy-status').textContent='';window.location.href='mailto:Vinhquang.bdshn@gmail.com?subject='+encodeURIComponent('Yêu cầu tư vấn căn hộ Moonlight 2 An Lạc')+'&body='+encodeURIComponent(inquiry)});
document.querySelector('#copy-inquiry').addEventListener('click',async()=>{try{await navigator.clipboard.writeText(inquiry);document.querySelector('#copy-status').textContent='Đã sao chép. Dán nội dung vào email gửi Vinhquang.bdshn@gmail.com.'}catch{let area=document.querySelector('#copy-fallback');if(!area){area=document.createElement('textarea');area.id='copy-fallback';area.readOnly=true;document.querySelector('#form-result').append(area)}area.value=inquiry;area.focus();area.select();document.querySelector('#copy-status').textContent='Hãy sao chép nội dung trong ô và gửi tới Vinhquang.bdshn@gmail.com.'}});